            for j in range(w):
                if g[i][j]==c:
                    if not (uni_r[i] and g[i][0]==c) and not (uni_c[j] and g[0][j]==c):
                        return False
        return True
    sep_r=[uni_r[i] and only_lines(g[i][0]) for i in range(h)]
    sep_c=[uni_c[j] and only_lines(g[0][j]) for j in range(w)]
    def bands(flags):
        res=[];cur=[]
        for i in range(len(flags)):
            if not flags[i]: cur.append(i)
            else:
                if cur: res.append(cur); cur=[]
        if cur: res.append(cur)
        return res
    rbands=bands(sep_r); cbands=bands(sep_c)
    cells=[(rb,cb) for rb in rbands for cb in cbands]
